import express from 'express';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';
import {
  ApiError,
  create,
  getById,
  list,
  listTags,
  update,
  remove,
} from './bookmarks.js';

const __dirname = dirname(fileURLToPath(import.meta.url));
const PUBLIC_DIR = join(__dirname, '..', 'public');

export function createApp() {
  const app = express();
  app.use(express.json());

  const api = express.Router();

  // Wrap async handlers so rejections reach the error middleware.
  const wrap = (fn) => (req, res, next) => Promise.resolve(fn(req, res, next)).catch(next);

  // GET /api/bookmarks?q=&tag=  (FR-006, FR-011, FR-012, FR-013)
  api.get(
    '/bookmarks',
    wrap((req, res) => {
      const { q, tag } = req.query;
      res.json(list({ q, tag }));
    })
  );

  // GET /api/bookmarks/:id
  api.get(
    '/bookmarks/:id',
    wrap((req, res) => {
      const bm = getById(Number(req.params.id));
      if (!bm) throw new ApiError(404, 'not_found', 'Bookmark not found.');
      res.json(bm);
    })
  );

  // POST /api/bookmarks  (FR-001..004, FR-010, FR-014)
  api.post(
    '/bookmarks',
    wrap(async (req, res) => {
      const created = await create(req.body || {});
      res.status(201).json(created);
    })
  );

  // PUT /api/bookmarks/:id  (FR-008)
  api.put(
    '/bookmarks/:id',
    wrap((req, res) => {
      const updated = update(Number(req.params.id), req.body || {});
      res.json(updated);
    })
  );

  // DELETE /api/bookmarks/:id  (FR-009)
  api.delete(
    '/bookmarks/:id',
    wrap((req, res) => {
      remove(Number(req.params.id));
      res.status(204).end();
    })
  );

  // GET /api/tags  (FR-012)
  api.get(
    '/tags',
    wrap((req, res) => {
      res.json({ tags: listTags() });
    })
  );

  app.use('/api', api);

  // Static UI.
  app.use(express.static(PUBLIC_DIR));

  // Centralised error handler → { error, message } (contracts/api.md).
  // eslint-disable-next-line no-unused-vars
  app.use((err, req, res, next) => {
    if (err instanceof ApiError) {
      return res.status(err.status).json({
        error: err.code,
        message: err.message,
        ...err.extra,
      });
    }
    console.error(err);
    res.status(500).json({ error: 'server_error', message: 'Something went wrong.' });
  });

  return app;
}

// Start the server unless imported by a test.
const isMain = process.argv[1] === fileURLToPath(import.meta.url);
if (isMain) {
  const port = Number(process.env.PORT) || 4000;
  const app = createApp();
  app.listen(port, '0.0.0.0', () => {
    console.log(`Bookmark Manager listening on http://0.0.0.0:${port}`);
  });
}
// Bookmark data-access and business rules (data-model.md, contracts/api.md).
// Depends on db.js (storage), url.js (validate/normalise/dedupe), and
// title-fetch.js (best-effort auto-title).

import { getDb } from './db.js';
import { normalize, dedupeKey } from './url.js';
import { fetchTitle } from './title-fetch.js';

/** Error carrying an HTTP status + machine code for the API layer. */
export class ApiError extends Error {
  constructor(status, code, message, extra = {}) {
    super(message);
    this.status = status;
    this.code = code;
    this.extra = extra;
  }
}

function nowIso() {
  // Full ISO-8601 with millisecond precision so quick successive edits produce
  // distinct updated_at values and ordering stays stable.
  return new Date().toISOString();
}

// ---- Tag helpers -----------------------------------------------------------

function normalizeTags(tags) {
  if (tags == null) return [];
  if (!Array.isArray(tags)) {
    throw new ApiError(400, 'invalid_tags', 'Tags must be a list of labels.');
  }
  const seen = new Map(); // lowercased -> original trimmed
  for (const t of tags) {
    if (typeof t !== 'string') continue;
    const trimmed = t.trim();
    if (trimmed === '') continue;
    const key = trimmed.toLowerCase();
    if (!seen.has(key)) seen.set(key, trimmed);
  }
  return [...seen.values()];
}

function upsertTag(db, name) {
  const existing = db
    .prepare('SELECT id FROM tags WHERE name = ? COLLATE NOCASE')
    .get(name);
  if (existing) return existing.id;
  const info = db.prepare('INSERT INTO tags(name) VALUES (?)').run(name);
  return info.lastInsertRowid;
}

function setBookmarkTags(db, bookmarkId, tagNames) {
  db.prepare('DELETE FROM bookmark_tags WHERE bookmark_id = ?').run(bookmarkId);
  const link = db.prepare(
    'INSERT OR IGNORE INTO bookmark_tags(bookmark_id, tag_id) VALUES (?, ?)'
  );
  for (const name of tagNames) {
    link.run(bookmarkId, upsertTag(db, name));
  }
  pruneOrphanTags(db);
}

function pruneOrphanTags(db) {
  db.prepare(
    'DELETE FROM tags WHERE id NOT IN (SELECT DISTINCT tag_id FROM bookmark_tags)'
  ).run();
}

function tagsFor(db, bookmarkId) {
  return db
    .prepare(
      `SELECT t.name FROM tags t
       JOIN bookmark_tags bt ON bt.tag_id = t.id
       WHERE bt.bookmark_id = ?
       ORDER BY t.name COLLATE NOCASE`
    )
    .all(bookmarkId)
    .map((r) => r.name);
}

function toResource(db, row) {
  return {
    id: row.id,
    url: row.url,
    title: row.title,
    notes: row.notes,
    tags: tagsFor(db, row.id),
    created_at: row.created_at,
    updated_at: row.updated_at,
  };
}

// ---- Create (US1) ----------------------------------------------------------

/**
 * Create a bookmark. Normalises + validates the address, auto-fetches a title
 * when none is supplied, detects duplicates, and persists.
 * @returns {Promise<object>} the created Bookmark resource
 * @throws {ApiError} 400 invalid address, 409 duplicate without confirm
 */
export async function create({ url, title, notes, tags, confirmDuplicate } = {}) {
  const db = getDb();

  let normalizedUrl;
  try {
    normalizedUrl = normalize(url);
  } catch (e) {
    throw new ApiError(400, 'invalid_url', e.message);
  }

  const key = dedupeKey(normalizedUrl);
  const cleanTags = normalizeTags(tags);
  const cleanNotes = typeof notes === 'string' ? notes.trim() : '';

  if (!confirmDuplicate) {
    const dup = db
      .prepare('SELECT id FROM bookmarks WHERE url_key = ?')
      .get(key);
    if (dup) {
      throw new ApiError(
        409,
        'already_saved',
        'This address is already saved. Save it again anyway?',
        { existingId: dup.id }
      );
    }
  }

  // Resolve the title: user-provided wins; else best-effort fetch; else address.
  let resolvedTitle = typeof title === 'string' ? title.trim() : '';
  if (resolvedTitle === '') {
    const fetched = await fetchTitle(normalizedUrl);
    resolvedTitle = fetched && fetched.trim() !== '' ? fetched.trim() : normalizedUrl;
  }

  const ts = nowIso();
  const insert = db.prepare(
    `INSERT INTO bookmarks(url, title, notes, url_key, created_at, updated_at)
     VALUES (@url, @title, @notes, @url_key, @created_at, @updated_at)`
  );

  const tx = db.transaction(() => {
    const info = insert.run({
      url: normalizedUrl,
      title: resolvedTitle,
      notes: cleanNotes,
      url_key: key,
      created_at: ts,
      updated_at: ts,
    });
    setBookmarkTags(db, info.lastInsertRowid, cleanTags);
    return info.lastInsertRowid;
  });

  const id = tx();
  return getById(id);
}

// ---- Read / list (US2, US4) ------------------------------------------------

/** @returns {object|null} */
export function getById(id) {
  const db = getDb();
  const row = db.prepare('SELECT * FROM bookmarks WHERE id = ?').get(id);
  return row ? toResource(db, row) : null;
}

/**
 * List bookmarks newest-first, with optional search term (q) and tag filter.
 * @param {{q?: string, tag?: string}} options
 * @returns {{bookmarks: object[], total: number, matched: number}}
 */
export function list({ q, tag } = {}) {
  const db = getDb();
  const total = db.prepare('SELECT COUNT(*) AS n FROM bookmarks').get().n;

  const where = [];
  const params = {};

  if (typeof tag === 'string' && tag.trim() !== '') {
    where.push(`b.id IN (
      SELECT bt.bookmark_id FROM bookmark_tags bt
      JOIN tags t ON t.id = bt.tag_id
      WHERE t.name = @tag COLLATE NOCASE
    )`);
    params.tag = tag.trim();
  }

  if (typeof q === 'string' && q.trim() !== '') {
    params.q = `%${q.trim().toLowerCase()}%`;
    where.push(`(
      LOWER(b.title) LIKE @q OR
      LOWER(b.url) LIKE @q OR
      LOWER(b.notes) LIKE @q OR
      b.id IN (
        SELECT bt.bookmark_id FROM bookmark_tags bt
        JOIN tags t ON t.id = bt.tag_id
        WHERE LOWER(t.name) LIKE @q
      )
    )`);
  }

  const sql =
    `SELECT b.* FROM bookmarks b` +
    (where.length ? ` WHERE ${where.join(' AND ')}` : '') +
    ` ORDER BY b.created_at DESC, b.id DESC`;

  const rows = db.prepare(sql).all(params);
  const bookmarks = rows.map((r) => toResource(db, r));
  return { bookmarks, total, matched: bookmarks.length };
}

/** @returns {string[]} existing tag names */
export function listTags() {
  const db = getDb();
  return db
    .prepare('SELECT name FROM tags ORDER BY name COLLATE NOCASE')
    .all()
    .map((r) => r.name);
}

// ---- Update / delete (US3) -------------------------------------------------

/**
 * Update fields of an existing bookmark. Any of url/title/notes/tags may be
 * provided. Refreshes updated_at. Re-validates url when supplied.
 * @returns {object} the updated resource
 * @throws {ApiError} 404 not found, 400 invalid url
 */
export function update(id, fields = {}) {
  const db = getDb();
  const existing = db.prepare('SELECT * FROM bookmarks WHERE id = ?').get(id);
  if (!existing) throw new ApiError(404, 'not_found', 'Bookmark not found.');

  const next = {
    url: existing.url,
    title: existing.title,
    notes: existing.notes,
    url_key: existing.url_key,
  };

  if (fields.url !== undefined) {
    let normalizedUrl;
    try {
      normalizedUrl = normalize(fields.url);
    } catch (e) {
      throw new ApiError(400, 'invalid_url', e.message);
    }
    next.url = normalizedUrl;
    next.url_key = dedupeKey(normalizedUrl);
  }

  if (fields.title !== undefined) {
    const t = typeof fields.title === 'string' ? fields.title.trim() : '';
    next.title = t === '' ? next.url : t;
  }

  if (fields.notes !== undefined) {
    next.notes = typeof fields.notes === 'string' ? fields.notes.trim() : '';
  }

  const ts = nowIso();
  const tx = db.transaction(() => {
    db.prepare(
      `UPDATE bookmarks
       SET url = @url, title = @title, notes = @notes, url_key = @url_key,
           updated_at = @updated_at
       WHERE id = @id`
    ).run({ ...next, updated_at: ts, id });

    if (fields.tags !== undefined) {
      setBookmarkTags(db, id, normalizeTags(fields.tags));
    }
  });
  tx();

  return getById(id);
}

/**
 * Permanently delete a bookmark.
 * @throws {ApiError} 404 not found
 */
export function remove(id) {
  const db = getDb();
  const info = db.prepare('DELETE FROM bookmarks WHERE id = ?').run(id);
  if (info.changes === 0) {
    throw new ApiError(404, 'not_found', 'Bookmark not found.');
  }
  pruneOrphanTags(db);
}
// SQLite connection and idempotent schema initialisation (data-model.md).
// A single local database file provides persistence across restarts (FR-005).

import Database from 'better-sqlite3';
import { mkdirSync } from 'node:fs';
import { dirname } from 'node:path';

const DEFAULT_DB_PATH = 'data/bookmarks.db';

let db;

/**
 * Open (once) and return the shared database connection, creating the schema if
 * it does not yet exist. Honours DB_PATH env var; ":memory:" is used by tests.
 * @returns {import('better-sqlite3').Database}
 */
export function getDb() {
  if (db) return db;

  const dbPath = process.env.DB_PATH || DEFAULT_DB_PATH;
  if (dbPath !== ':memory:') {
    mkdirSync(dirname(dbPath), { recursive: true });
  }

  db = new Database(dbPath);
  db.pragma('journal_mode = WAL');
  db.pragma('foreign_keys = ON');
  initSchema(db);
  return db;
}

function initSchema(database) {
  database.exec(`
    CREATE TABLE IF NOT EXISTS bookmarks (
      id         INTEGER PRIMARY KEY AUTOINCREMENT,
      url        TEXT    NOT NULL,
      title      TEXT    NOT NULL,
      notes      TEXT    NOT NULL DEFAULT '',
      url_key    TEXT    NOT NULL,
      created_at TEXT    NOT NULL,
      updated_at TEXT    NOT NULL
    );

    CREATE TABLE IF NOT EXISTS tags (
      id   INTEGER PRIMARY KEY AUTOINCREMENT,
      name TEXT    NOT NULL
    );

    CREATE TABLE IF NOT EXISTS bookmark_tags (
      bookmark_id INTEGER NOT NULL REFERENCES bookmarks(id) ON DELETE CASCADE,
      tag_id      INTEGER NOT NULL REFERENCES tags(id) ON DELETE CASCADE,
      PRIMARY KEY (bookmark_id, tag_id)
    );

    CREATE INDEX IF NOT EXISTS idx_bookmarks_url_key ON bookmarks(url_key);
    CREATE INDEX IF NOT EXISTS idx_bookmarks_created_at ON bookmarks(created_at DESC);
    CREATE UNIQUE INDEX IF NOT EXISTS idx_tags_name ON tags(name COLLATE NOCASE);
  `);
}

/**
 * Test helper: reset the module-level connection (e.g. between test files).
 */
export function closeDb() {
  if (db) {
    db.close();
    db = undefined;
  }
}
// Best-effort page-title fetch (FR-004).
// Fetches the target page with a short timeout and extracts the <title>.
// On ANY failure (network error, timeout, non-HTML, missing title) it returns
// null so the caller can fall back to the user-provided title or the address.
// This function never throws to the caller.

const FETCH_TIMEOUT_MS = 5000;
const MAX_BYTES = 512 * 1024; // only need the <head>; cap the read

/**
 * @param {string} url a normalised http/https URL
 * @returns {Promise<string|null>} the page title, or null if unavailable
 */
export async function fetchTitle(url) {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), FETCH_TIMEOUT_MS);
  try {
    const res = await fetch(url, {
      signal: controller.signal,
      redirect: 'follow',
      headers: { 'User-Agent': 'BookmarkManager/1.0 (+title-fetch)' },
    });
    if (!res.ok) return null;

    const contentType = res.headers.get('content-type') || '';
    if (!contentType.includes('html')) return null;

    const html = await readCapped(res, MAX_BYTES);
    return extractTitle(html);
  } catch {
    // Timeout, DNS failure, connection refused, etc. — fall back gracefully.
    return null;
  } finally {
    clearTimeout(timer);
  }
}

async function readCapped(res, maxBytes) {
  // Prefer streaming so we can stop once we have the <head>; fall back to text().
  if (!res.body || typeof res.body.getReader !== 'function') {
    const full = await res.text();
    return full.slice(0, maxBytes);
  }
  const reader = res.body.getReader();
  const decoder = new TextDecoder();
  let out = '';
  let received = 0;
  while (received < maxBytes) {
    const { done, value } = await reader.read();
    if (done) break;
    received += value.length;
    out += decoder.decode(value, { stream: true });
    if (/<\/title>/i.test(out)) break; // got the title; stop early
  }
  try {
    await reader.cancel();
  } catch {
    // ignore
  }
  return out;
}

/**
 * Extract and clean the <title> text from an HTML string.
 * @param {string} html
 * @returns {string|null}
 */
export function extractTitle(html) {
  if (typeof html !== 'string') return null;
  const match = html.match(/<title[^>]*>([\s\S]*?)<\/title>/i);
  if (!match) return null;
  const raw = decodeEntities(match[1]).replace(/\s+/g, ' ').trim();
  return raw.length > 0 ? raw : null;
}

function decodeEntities(text) {
  return text
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&apos;/g, "'")
    .replace(/&#(\d+);/g, (_, n) => String.fromCodePoint(Number(n)))
    .replace(/&#x([0-9a-fA-F]+);/g, (_, n) => String.fromCodePoint(parseInt(n, 16)));
}
// URL validation, normalisation, and dedupe-key helpers.
// Implements FR-002 (validate), FR-003 (normalise missing scheme), and the
// dedupe key used for FR-010 (duplicate detection).

/**
 * Normalise a user-entered address into a canonical http/https URL string.
 * - Trims surrounding whitespace.
 * - Prepends "https://" when no scheme is present (FR-003).
 * - Rejects anything that is not a valid http/https URL (FR-002).
 *
 * @param {string} input
 * @returns {string} the normalised absolute URL
 * @throws {Error} with a user-actionable message when the address is invalid
 */
export function normalize(input) {
  if (typeof input !== 'string' || input.trim() === '') {
    throw new Error('Please enter a web address.');
  }
  let candidate = input.trim();

  // If there is no scheme (e.g. "example.com/path"), default to https.
  // A leading "//" is treated as scheme-relative and also gets https.
  const schemeMatch = candidate.match(/^([a-zA-Z][a-zA-Z0-9+.-]*):\/\//);
  // A bare scheme like "javascript:..." or "mailto:..." — a scheme token with no
  // dot (to avoid mistaking "example.com:8080" for a scheme) followed by ":".
  const bareScheme = candidate.match(/^([a-zA-Z][a-zA-Z0-9+.-]*):(?!\/\/)/);

  if (schemeMatch) {
    const scheme = schemeMatch[1].toLowerCase();
    if (scheme !== 'http' && scheme !== 'https') {
      throw new Error('Only http and https web addresses are supported.');
    }
  } else if (bareScheme && !bareScheme[1].includes('.')) {
    const scheme = bareScheme[1].toLowerCase();
    if (scheme !== 'http' && scheme !== 'https') {
      throw new Error('Only http and https web addresses are supported.');
    }
  } else if (candidate.startsWith('//')) {
    candidate = 'https:' + candidate;
  } else {
    candidate = 'https://' + candidate;
  }

  let url;
  try {
    url = new URL(candidate);
  } catch {
    throw new Error('That does not look like a valid web address.');
  }

  if (url.protocol !== 'http:' && url.protocol !== 'https:') {
    throw new Error('Only http and https web addresses are supported.');
  }
  if (!url.hostname || !url.hostname.includes('.')) {
    throw new Error('That does not look like a valid web address.');
  }

  return url.toString();
}

/**
 * Compute a normalised dedupe key for an address so that trivially different
 * spellings of the same page collapse together (FR-010). Uses lowercased host
 * plus path, ignoring a trailing slash, and ignoring scheme, query, and fragment.
 *
 * @param {string} normalizedUrl a URL string (ideally already normalised)
 * @returns {string}
 */
export function dedupeKey(normalizedUrl) {
  const url = new URL(normalizedUrl);
  const host = url.hostname.toLowerCase();
  let path = url.pathname || '/';
  if (path.length > 1 && path.endsWith('/')) {
    path = path.slice(0, -1);
  }
  return host + path;
}
// Bookmark Manager UI logic. Talks to the JSON API in src/server.js.
// Covers US1 (save), US2 (browse/open), US3 (edit/delete), US4 (search/tags).

const listEl = document.getElementById('bookmark-list');
const emptyState = document.getElementById('empty-state');
const noResults = document.getElementById('no-results');
const listRegion = document.getElementById('list-region');
const searchInput = document.getElementById('search');
const tagFilter = document.getElementById('tag-filter');
const clearFiltersBtn = document.getElementById('clear-filters');

const formOverlay = document.getElementById('form-overlay');
const form = document.getElementById('bookmark-form');
const formTitle = document.getElementById('form-title');
const idField = document.getElementById('bookmark-id');
const urlField = document.getElementById('field-url');
const titleField = document.getElementById('field-title');
const notesField = document.getElementById('field-notes');
const tagsField = document.getElementById('field-tags');
const formError = document.getElementById('form-error');
const dupWarning = document.getElementById('dup-warning');
const dupMessage = document.getElementById('dup-message');
const formSubmit = document.getElementById('form-submit');

const confirmOverlay = document.getElementById('confirm-overlay');
const confirmMessage = document.getElementById('confirm-message');
let pendingDeleteId = null;
let pendingConfirmDuplicate = false;

// ---- API helpers -----------------------------------------------------------

async function api(path, options = {}) {
  const res = await fetch(path, {
    headers: { 'Content-Type': 'application/json' },
    ...options,
  });
  if (res.status === 204) return null;
  const data = await res.json().catch(() => ({}));
  if (!res.ok) {
    const err = new Error(data.message || 'Request failed');
    err.code = data.error;
    err.data = data;
    err.status = res.status;
    throw err;
  }
  return data;
}

function escapeHtml(s) {
  return String(s)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

// ---- Rendering -------------------------------------------------------------

function bookmarkNode(bm) {
  const li = document.createElement('li');
  li.className = 'bookmark';
  li.dataset.id = bm.id;

  const tagsHtml = bm.tags.length
    ? `<div class="tag-row">${bm.tags
        .map((t) => `<span class="tag">${escapeHtml(t)}</span>`)
        .join('')}</div>`
    : '';
  const notesHtml = bm.notes
    ? `<p class="bookmark-notes">${escapeHtml(bm.notes)}</p>`
    : '';

  li.innerHTML = `
    <div class="bookmark-main">
      <a class="bookmark-title" href="${escapeHtml(bm.url)}" target="_blank" rel="noopener noreferrer" title="${escapeHtml(bm.title)}">${escapeHtml(bm.title)}</a>
      <span class="bookmark-url" title="${escapeHtml(bm.url)}">${escapeHtml(bm.url)}</span>
      ${notesHtml}
      ${tagsHtml}
    </div>
    <div class="bookmark-actions">
      <button class="btn btn-small" type="button" data-action="edit">Edit</button>
      <button class="btn btn-small" type="button" data-action="delete">Delete</button>
    </div>
  `;
  return li;
}

let lastTotal = 0;

async function refresh() {
  const params = new URLSearchParams();
  const q = searchInput.value.trim();
  const tag = tagFilter.value;
  if (q) params.set('q', q);
  if (tag) params.set('tag', tag);

  const { bookmarks, total, matched } = await api(`/api/bookmarks?${params.toString()}`);
  lastTotal = total;

  listEl.innerHTML = '';
  for (const bm of bookmarks) listEl.appendChild(bookmarkNode(bm));

  const filtering = Boolean(q || tag);
  emptyState.hidden = total !== 0;
  noResults.hidden = !(total > 0 && matched === 0 && filtering);
  clearFiltersBtn.hidden = !filtering;

  markReady();
}

async function refreshTags() {
  const { tags } = await api('/api/tags');
  const current = tagFilter.value;
  tagFilter.innerHTML = '<option value="">All tags</option>';
  for (const t of tags) {
    const opt = document.createElement('option');
    opt.value = t;
    opt.textContent = t;
    tagFilter.appendChild(opt);
  }
  if (tags.includes(current)) tagFilter.value = current;
}

let readyMarked = false;
function markReady() {
  if (readyMarked) return;
  readyMarked = true;
  listRegion.setAttribute('data-harness-ready', 'true');
}

// ---- Add / edit form -------------------------------------------------------

function openForm(bm = null) {
  form.reset();
  formError.hidden = true;
  dupWarning.hidden = true;
  pendingConfirmDuplicate = false;
  formSubmit.textContent = 'Save';

  if (bm) {
    formTitle.textContent = 'Edit bookmark';
    idField.value = bm.id;
    urlField.value = bm.url;
    titleField.value = bm.title;
    notesField.value = bm.notes;
    tagsField.value = bm.tags.join(', ');
  } else {
    formTitle.textContent = 'Add bookmark';
    idField.value = '';
  }
  formOverlay.hidden = false;
  urlField.focus();
}

function closeForm() {
  formOverlay.hidden = true;
}

function parseTags(value) {
  return value
    .split(',')
    .map((t) => t.trim())
    .filter((t) => t !== '');
}

form.addEventListener('submit', async (e) => {
  e.preventDefault();
  formError.hidden = true;

  const id = idField.value;
  const payload = {
    url: urlField.value,
    title: titleField.value,
    notes: notesField.value,
    tags: parseTags(tagsField.value),
  };

  try {
    if (id) {
      await api(`/api/bookmarks/${id}`, {
        method: 'PUT',
        body: JSON.stringify(payload),
      });
    } else {
      await api('/api/bookmarks', {
        method: 'POST',
        body: JSON.stringify({ ...payload, confirmDuplicate: pendingConfirmDuplicate }),
      });
    }
    closeForm();
    await Promise.all([refresh(), refreshTags()]);
  } catch (err) {
    if (err.status === 409 && err.code === 'already_saved') {
      // Offer to save the duplicate anyway.
      pendingConfirmDuplicate = true;
      dupMessage.textContent = err.message;
      dupWarning.hidden = false;
      formSubmit.textContent = 'Save anyway';
      return;
    }
    formError.textContent = err.message;
    formError.hidden = false;
  }
});

// ---- Delete confirmation ---------------------------------------------------

function openConfirm(id, title) {
  pendingDeleteId = id;
  confirmMessage.textContent = `"${title}" will be permanently removed. This cannot be undone.`;
  confirmOverlay.hidden = false;
}

function closeConfirm() {
  pendingDeleteId = null;
  confirmOverlay.hidden = true;
}

document.getElementById('confirm-delete').addEventListener('click', async () => {
  if (pendingDeleteId == null) return;
  await api(`/api/bookmarks/${pendingDeleteId}`, { method: 'DELETE' });
  closeConfirm();
  await Promise.all([refresh(), refreshTags()]);
});

// ---- Event wiring ----------------------------------------------------------

document.getElementById('add-btn').addEventListener('click', () => openForm());
document.getElementById('form-cancel').addEventListener('click', closeForm);
document.getElementById('confirm-cancel').addEventListener('click', closeConfirm);

listEl.addEventListener('click', async (e) => {
  const btn = e.target.closest('button[data-action]');
  if (!btn) return;
  const li = btn.closest('.bookmark');
  const id = Number(li.dataset.id);
  if (btn.dataset.action === 'edit') {
    const bm = await api(`/api/bookmarks/${id}`);
    openForm(bm);
  } else if (btn.dataset.action === 'delete') {
    const title = li.querySelector('.bookmark-title').textContent;
    openConfirm(id, title);
  }
});

let searchTimer;
searchInput.addEventListener('input', () => {
  clearTimeout(searchTimer);
  searchTimer = setTimeout(refresh, 180);
});
tagFilter.addEventListener('change', refresh);

function clearFilters() {
  searchInput.value = '';
  tagFilter.value = '';
  refresh();
}
clearFiltersBtn.addEventListener('click', clearFilters);

document.body.addEventListener('click', (e) => {
  if (e.target.matches('[data-open-add]')) openForm();
  if (e.target.matches('[data-clear-filters]')) clearFilters();
});

// Close overlays when clicking the backdrop.
for (const overlay of [formOverlay, confirmOverlay]) {
  overlay.addEventListener('click', (e) => {
    if (e.target === overlay) overlay.hidden = true;
  });
}

// ---- Boot ------------------------------------------------------------------

(async function init() {
  try {
    await Promise.all([refresh(), refreshTags()]);
  } catch (err) {
    console.error(err);
    // Still mark ready so the harness/user sees a usable (if empty) page.
    markReady();
  }
})();
