  --border: #e2e5ea;
  --text: #1c2430;
  --muted: #6b7688;
  --primary: #2f6bff;
  --primary-hover: #1f57e0;
  --danger: #d9463e;
  --shadow: 0 1px 3px rgba(20, 30, 50, 0.08), 0 6px 20px rgba(20, 30, 50, 0.06);
}

* {
  box-sizing: border-box;
}

/* The hidden attribute must win over component display rules below. */
